describe("slugify", () => {
  test("transforms basic text with punctuation to slug", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });

  test("REQ-001: converts text to lowercase", () => {
    expect(slugify("HELLO")).toBe("hello");
    expect(slugify("CamelCaseText")).toBe("camelcasetext");
  });

  test("REQ-002: replaces spaces with hyphens", () => {
    expect(slugify("Foo Bar")).toBe("foo-bar");
    expect(slugify("Multi   Spaces")).toBe("multi-spaces");
  });

  test("REQ-002: replaces underscores with hyphens", () => {
    expect(slugify("Foo_Bar")).toBe("foo-bar");
    expect(slugify("Foo__Bar")).toBe("foo-bar");
  });

  test("REQ-003: removes non-whitelisted characters", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("Foo@Bar#123")).toBe("foobar123");
    expect(slugify("Special!@#Chars")).toBe("specialchars");
  });

  test("REQ-003: retains only a-z, 0-9, and hyphen", () => {
    expect(slugify("Test 123")).toBe("test-123");
    expect(slugify("a1b2c3")).toBe("a1b2c3");
  });

  test("REQ-004: collapses consecutive hyphens", () => {
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("Foo  Bar")).toBe("foo-bar");
    expect(slugify("Hello,,,World")).toBe("helloworld");
  });

  test("REQ-005: removes leading hyphens", () => {
    expect(slugify("  Foo  ")).toBe("foo");
    expect(slugify("---bar---")).toBe("bar");
    expect(slugify("!!!Hello")).toBe("hello");
  });

  test("REQ-005: removes trailing hyphens", () => {
    expect(slugify("Foo  ")).toBe("foo");
    expect(slugify("bar---")).toBe("bar");
  });

  test("REQ-006: handles empty string input", () => {
    expect(slugify("")).toBe("");
  });

  test("REQ-006: returns empty string for all-invalid input", () => {
    expect(slugify("!!!")).toBe("");
    expect(slugify("@@@")).toBe("");
    expect(slugify("---")).toBe("");
  });

  test("validates all examples from requirements", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("Foo__Bar")).toBe("foo-bar");
    expect(slugify("  Foo  ")).toBe("foo");
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("Test 123")).toBe("test-123");
    expect(slugify("CamelCaseText")).toBe("camelcasetext");
    expect(slugify("Multi   Spaces")).toBe("multi-spaces");
    expect(slugify("Special!@#Chars")).toBe("specialchars");
    expect(slugify("")).toBe("");
    expect(slugify("!!!")).toBe("");
    expect(slugify("---")).toBe("");
  });
});

